+        values[nz_index_tmp] =
+            (x[state_index_tmp] + std::cos(x[state_index_tmp + 2]) * offset_) *
+                Aj(k, 0) +
+            (x[state_index_tmp + 1]
+                + std::sin(x[state_index_tmp + 2]) * offset_) *
+                Aj(k, 1) -
+                bj(k, 0);  // ddk
+        ++nz_index_tmp;  // current_edges_num
+      }
+
+      // with respect to n
+      for (int k = 0; k < 4; ++k) {
+        values[nz_index_tmp] = -g_[k];  // eek
+        ++nz_index_tmp;  // 4
+      }
+    }
+    // update index
+    for (int jj = 0; jj < obstacles_num_; ++jj) {
+      nz_index += 4 * (horizon_ + 1) * obstacles_edges_num_(jj, 0);
+      nz_index += 13 * (horizon_ + 1);
+    }
+
+    // 5. load variable bounds as constraints
+    state_index = state_start_index_;
+    control_index = control_start_index_;
+    time_index = time_start_index_;
+    l_index = l_start_index_;
+    n_index = n_start_index_;
+
+    // start configuration
+    values[nz_index] = 1.0;
+    nz_index++;
+    values[nz_index] = 1.0;
+    nz_index++;
+    values[nz_index] = 1.0;
+    nz_index++;
+    values[nz_index] = 1.0;
+    nz_index++;
+
+    for (int i = 1; i < horizon_; ++i) {
+      values[nz_index] = 1.0;
+      nz_index++;
+      values[nz_index] = 1.0;
+      nz_index++;
+      values[nz_index] = 1.0;
+      nz_index++;
+    }
+
+    // end configuration
+    values[nz_index] = 1.0;
+    nz_index++;
+    values[nz_index] = 1.0;
+    nz_index++;
+    values[nz_index] = 1.0;
+    nz_index++;
+    values[nz_index] = 1.0;
+    nz_index++;
+
+    for (int i = 0; i < horizon_; ++i) {
+      values[nz_index] = 1.0;
+      nz_index++;
+      values[nz_index] = 1.0;
+      nz_index++;
+    }
+
+    for (int i = 0; i < horizon_ + 1; ++i) {
+      values[nz_index] = 1.0;
+      nz_index++;
+    }
+
+    for (int i = 0; i < lambda_horizon_; ++i) {
+      values[nz_index] = 1.0;
+      nz_index++;
+    }
+
+    for (int i = 0; i < miu_horizon_; ++i) {
+      values[nz_index] = 1.0;
+      nz_index++;
+    }
+
+    ADEBUG << "eval_jac_g, fulfilled obstacle constraint values";
+    CHECK_EQ(nz_index, static_cast<int>(nele_jac));
+  }
+
+  ADEBUG << "eval_jac_g done";
+  return true;
+}  // NOLINT
+
