-  result[0].set_x(dx + ref_point.x());
-  result[0].set_y(dy + ref_point.y());
-  for (std::uint32_t k = 1; k < n; ++k) {
-    dx += (vec_s[k] - vec_s[k - 1]) *
-          (std::cos(std::fmod(result[k - 1].theta(), s_two_pi_)) +
