+       }
+      }
+        notFound = false;
+     }
+     if (notFound) {
+       PyList_Append(pyobj_list, Py_BuildValue("s",
+           ConnectChar("Channel cannot be found: ", channel_name.c_str())));
+     }
+     return pyobj_list;
+  }
