-TF2SIMD_FORCE_INLINE Matrix3x3 
-Matrix3x3::inverse() const
-{
-	Vector3 co(cofac(1, 1, 2, 2), cofac(1, 2, 2, 0), cofac(1, 0, 2, 1));
-	tf2Scalar det = (*this)[0].dot(co);
