-TF2SIMD_FORCE_INLINE tf2Scalar tf2Fsel(tf2Scalar a, tf2Scalar b, tf2Scalar c)
-{
-	return a >= 0 ? b : c;
-}
-#endif
-#define tf2Fsels(a,b,c) (tf2Scalar)tf2Fsel(a,b,c)
