+    help_str_ += "\nS: capture screen";
+    help_str_ += "\nA: capture video";
+    help_str_ += "\nI: show type id label";
+    if (show_type_id_label_) help_str_ += " (ON)";
+    help_str_ += "\nQ: show lane";
+    if (show_lane_) help_str_ += " (ON)";
