+  std::vector<ObstacleEdge> lateral_edges;
+  lateral_edges.emplace_back(
+      1, std::numeric_limits<double>::lowest(), 0.0, 0.0, "l_min");
+  lateral_edges.emplace_back(
+      0, l_min, 0.0, 0.0, "l_min");
+  lateral_edges.emplace_back(
+      1, l_max, 0.0, 0.0, "l_max");
+  lateral_edges.emplace_back(
