+    if (cur_segment->size() < 2 || next_segment->size() < 2) {
+      AERROR << "Single point line_segments vec not expected";
+      return false;
+    }
+    size_t cur_segments_size = cur_segment->size();
+    auto cur_second_to_last_point = cur_segment->at(cur_segments_size - 2);
