+        0.0) {
+      cur_segment->push_back(next_second_point);
+      next_segment->erase(next_segment->begin(), next_segment->begin() + 2);
+      if (next_segment->empty()) {
+        line_segments_vec->erase(next_segment);
+      }
+    } else {
+      ++cur_segment;
+    }
+  }
+  return true;
