+  } else {
+    std::weak_ptr<TimerTask> task_wptr = this->task_;
+    task_->callback = [this, task_wptr]() {
+      auto start = std::chrono::steady_clock::now();
+      this->timer_opt_.callback();
+      auto end = std::chrono::steady_clock::now();
+      uint64_t execute_time_ms =
