-  ADCTrajectory trajectory_to_end_pb_;
-
-  OpenSpaceThreadData thread_data_;
-  std::future<void> task_future_;
-  std::atomic<bool> is_stop_{false};
-  std::atomic<bool> trajectory_updated_{false};
-  std::mutex open_space_mutex_;
-};
-
-}  // namespace planning
-}  // namespace apollo

