+void CosThetaReferenceLineSmoother::NormalizePoints(
+    std::vector<Eigen::Vector2d>* xy_points) {
+  zero_x_ = xy_points->front().x();
+  zero_y_ = xy_points->front().y();
+
+  std::for_each(xy_points->begin(), xy_points->end(),
+                [this](Eigen::Vector2d& p) {
