+          reference_line_info.GetNeighborLaneInfo(LaneType::RightReverse,
+              curr_s, &neighbor_lane_id, &curr_neighbor_lane_width)) {
+        is_feasible_window = false;
+        break;
+      }
+    }
+    if (is_feasible_window) {
+      has_a_feasible_window = true;
