+  Eigen::MatrixXd l_warm_up_ =
+      Eigen::MatrixXd::Zero(l_warm_up_vec[0].rows(), l_warm_start_size);
+  Eigen::MatrixXd n_warm_up_ =
+      Eigen::MatrixXd::Zero(n_warm_up_vec[0].rows(), n_warm_start_size);
+  Eigen::MatrixXd dual_l_result_ds_ =
