+  const double dy1 = sin_heading * half_length;
+  const double dx2 = sin_heading * half_width;
+  const double dy2 = -cos_heading * half_width;
+
+  Vec2d left_top(pull_over_x - dx1 + dx2, pull_over_y - dy1 + dy2);
