-
-    } else {
-      for (size_t j = 2 + shift; j <= 7 + shift; ++j) {
-        idx_map_.insert(std::pair<std::pair<size_t, size_t>, size_t>(
-            std::pair<size_t, size_t>(i, j), index));
-        index++;
-      }
-      shift += 2;
-    }
-  }
-}
