-
-  const auto& inlane_point =
-      reference_line.GetReferencePoint(stop_point_sl.s());
-
-  inlane_stop_point_.set_x(inlane_point.x());
-  inlane_stop_point_.set_y(inlane_point.y());
-
-  PointENU stop_point;
