+template<typename T>
+bool UDPBridgeReceiverComponent<T>::IsTimeout(double time_stamp) {
+  double cur_time = apollo::common::time::Clock::NowInSeconds();
+  if (cur_time < time_stamp) {
+    return true;
+  }
+  if (FLAGS_timeout < cur_time - time_stamp) {
+    return true;
+  }
+  return false;
